      "Özel yağlar, emülgatörler, yağ ve şeker kusması kontrolü.",
      "Kalite kontrol, fizikokimyasal analizler, duyusal yöntemler.",
      "Raf ömrü, ambalajlama, depolama; mikrobiyal ve kimyasal güvenlik.",
