    "content": "Gıda ambalajlamanın önemi, ambalaj materyallerinin özellikleri, ambalajlama teknikleri, depolama teknikleri, çeşitli gıdaların depolanması ve depolama sırasında meydana gelen değişimler.",
    "methods": "Ders anlatımıu,sunum ve laboratuar uygulamaları",
