      "Gıda ambalajlama teknolojisinde kullanılan yeni teknikler için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Gıda ambalajlama teknolojisinde kullanılan yeni teknikler faaliyetlerindeki etkileri ve riskleri değerlendirir.",
