      "Ambalaj materyallerinin özellikleri I- Cam ve kağıt esaslı materyaller",
      "Ambalaj materyallerinin özellikleri II- Metal ve plastik esaslı materyaller",
      "Gıda ambalajlama sistemleri I- Aseptik ambalajlama",
