      "Gıda-ambalaj ve Mikroorganizma/böcek-ambalaj etkileşimleri",
      "Ambalaj kontrolü, ambalajlamada güvenlik ve yasal durum",
      "Gıdaların depolanması ve depolama sırasında meydana gelen değişimler",
      "Tahıl ve tahıl ürünlerinin depolanması",
      "Et ve et ürünlerinin depolanması",
