    "credit": 3,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Doç. Dr. ÖZGE SÜFER",
    "purpose": "Bu dersin amacı, gıdaların ısıl iletim, ısıl difüzyon, özgül ısı, ısıl iletkenlik ve faz değişimi gibi temel ısıl özelliklerini bilimsel temelleriyle açıklamak; bu özelliklerin gıda işleme, pişirme, pastörizasyon, sterilizasyon, dondurma ve çözündürme gibi ısıl işlemler üzerindeki etkilerini değerlendirme becerisi kazandırmaktır. Öğrencilerin gıdaların ısıl davranışını modelleyebilmesi, deneysel ölçüm yöntemlerini anlayabilmesi ve ısıl özelliklere bağlı proses tasarımı yapabilmesi hedeflenmektedir.",
    "content": "Gıdaların özgül ısı, ısıl iletkenlik, ısıl difüzyon ve faz değişimi gibi temel ısıl özellikleri; ısı transferi mekanizmaları (iletim, konveksiyon, radyasyon); gıdalarda ısıl özelliklerin bileşime, sıcaklığa ve fiziksel yapıya bağlı değişimi; ısıl özelliklerin deneysel olarak belirlenmesi; dondurma–çözündürme, pastörizasyon, sterilizasyon, pişirme ve soğutma gibi gıda proseslerinde ısıl özelliklerin rolü; ısı transferi modelleri ve proses tasarımına etkileri; ısıl davranışın kalite, mikrobiyal inaktivasyon ve enerji verimliliği üzerindeki sonuçlarının değerlendirilmesi.",
    "methods": "Ders anlatımı, görsel sunumlar, örnek problem çözme uygulamaları, sınıf içi tartışmalar, laboratuvar/ölçüm yöntemlerinin gösterimi, vaka incelemeleri ve literatür değerlendirmeleri. Öğrencilerin aktif katılımını artırmak amacıyla kısa ödevler, hesaplama alıştırmaları ve grup çalışmaları uygulanır.",
    "resources": "Kaynaklar: 12; Ders Notları: Ders kapsamında kullanılacak materyaller; öğretim elemanı tarafından hazırlanan ders slaytları, örnek hesaplama notları, laboratuvar/ölçüm yöntemlerine ilişkin ek dokümanlar, güncel bilimsel makaleler ve ilgili kitap bölümleridir. Öğrenciler ders süresince sağlanan bu notları takip edecek ve gerektiğinde ek literatürden yararlanacaktır.",
    "sdgs": [
      "2",
      "9",
      "12"
    ],
    "outcomes": [
      "Gıdaların ısıl özellikleri kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Gıda muhafaza ve ambalajlama prosesleri alanındaki uygulamaları karşılaştırır.",
      "Gıdaların ısıl özellikleri için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Gıdaların ısıl özellikleri faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Gıdaların ısıl özellikleri bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Gıdaların ısıl özelliklerine giriş, temel kavramlar",
      "Özgül ısı ve gıdalarda ısı kapasitesinin bileşimle ilişkisi",
      "Isıl iletkenlik – tanım, ölçüm yöntemleri, gıdalarda iletkenlik modelleri",
      "Isıl difüzyon – hesaplamalar, sıcaklık değişimi ile davranış",
      "Faz değişimleri (donma, erime, buharlaşma) ve gıdalarda ısıl etkiler",
      "Isı transferi mekanizmaları (iletim, konveksiyon, radyasyon)",
      "Gıdalarda sıcaklık gradyentleri ve ısıl denge modelleri",
      "Pastörizasyon ve sterilizasyonda ısıl özelliklerin rolü",
      "Dondurma ve çözündürme süreçlerinde ısıl davranış",
      "Pişirme, soğutma ve ısıl proseslerde enerji dengesi",
      "Isıl özelliklerin deneysel belirlenmesi – ölçüm teknikleri",
      "Gıda endüstrisinde ısıl özellik uygulamaları ve güncel araştırmalar",
      "Gıdaların ısıl özellikleri: kapsam ve temel kavramlar",
      "Bozulma mekanizmaları",
      "Isı ve kütle aktarımı"
    ],
