      "Kurutmanın Temel Prensipleri",
      "Kurutma Hızı ve Hesaplanması",
      "Kurutma Hızına Etki Eden Faktörler",
      "Kurutma İşlemininin Modellenmesi",
      "Kurutulmuş Ürünlerin Yapısında Meydana Gelen Değişmeler",
      "Kurutulmuş Ürünlerde Kalite Kriterleri",
      "Doğal ve Yapay Kurutma",
      "Dondurarak Kurutma",
      "Kurutulmuş Ürünlerin Depolanması",
      "Gıdalarda kurutma sistemleri: kapsam ve temel kavramlar",
      "Bozulma mekanizmaları"
