    "content": "Proteinlerin yapıları ve sınıflandırmaları. Protein izolasyon ve saflaştırma teknikleri, protein analizleri. Proteinlerin besin değeri. Hayvansal ve bitkisel kaynaklı proteinler. Proteinlerin fonksiyonel özellikleri ve gıda ürünlerindeki uygulamaları.",
