    "content": "Kek bileşenleri ve işlevleri, Bisküvi bileşenleri ve işlevleri, Kraker bileşenleri ve işlevleri, Gofret bileşenleri ve işlevleri. Kek, bisküvi, kraker ve gofret üretim teknolojileri.",
