      "Fitokimyasallar için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Fitokimyasallar faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Fitokimyasallar bulgularını etik ve bilimsel ölçütlerle yorumlar."
